/**
 * Local pHash index for camera scanning, generated by scripts/prepare-hashes.js
 * and served from public/card-hashes.jsonl (JSON Lines). The build script
 * appends one entry line per face as it hashes — an append-only stream that
 * can be cancelled and resumed without losing work. Loaded once (idempotent)
 * into memory; the hash scanner matches photographed card artwork against it —
 * a fast, network-free identification channel that runs in parallel with OCR.
 *
 * File layout: an optional first meta line (`{"type":"meta",...}` carrying
 * region/threshold), then one entry per line (`{id,name,face,hashes}`) and
 * `{"type":"done","name":...}` completion markers (skipped here). Each entry
 * is one unique visual face (reprints sharing artwork collapse to one entry at
 * build time). `hashes` maps aspect-class key ("43" / "169") to the stored
 * variant hashes — fill outer, angle inner (see HASH_STORE_FILLS /
 * HASH_STORE_ANGLES in ocr/phash.ts). A missing file degrades gracefully:
 * the scanner simply reports "not ready" and OCR remains the only channel.
 */

import {
  HASH_ART_REGION,
  HASH_MATCH_THRESHOLD,
  type FrameRectLike
} from '../ocr/phash';

/** One unique visual face in the hash index. */
export interface CardHashEntry {
  /** Scryfall id of the printing this artwork came from (shared by DFC faces) */
  id: string;
  /** Display name (debug aid only — matching is purely visual) */
  name: string;
  /** 0 = front face, 1 = double-faced-card back */
  face: number;
  /** Aspect-class key -> variant hashes (fill outer × angle inner) */
  hashes: Record<string, string[]>;
}

/** Loaded index. `ready` is false when card-hashes.jsonl couldn't be loaded. */
export interface CardHashIndex {
  ready: boolean;
  entries: CardHashEntry[];
  /** Hashed region (fractions of the card zone) — from the file, code fallback */
  region: FrameRectLike;
  /** Max Hamming distance for a match — from the file, code fallback */
  threshold: number;
}

/** One parsed line of card-hashes.jsonl (meta, entry or done marker). */
interface CardHashLine {
  type?: string;
  region?: FrameRectLike;
  threshold?: number;
  id?: string;
  name?: string;
  face?: number;
  hashes?: Record<string, string[]>;
}

/** True when at least one aspect class carries a full list of 16-char hashes. */
function isUsableHashes(hashes: Record<string, string[]>): boolean {
  for (const list of Object.values(hashes)) {
    if (Array.isArray(list) && list.every(h => typeof h === 'string' && h.length === 16)) return true;
  }
  return false;
}

let index: CardHashIndex = {
  ready: false,
  entries: [],
  region: HASH_ART_REGION,
  threshold: HASH_MATCH_THRESHOLD
};
let loadPromise: Promise<CardHashIndex> | null = null;

/**
 * Loads the hash index (idempotent — concurrent calls share one fetch).
 * Resolves even on failure with `ready: false` so the scanner can simply skip
 * the hash channel and rely on OCR.
 */
export function ensureCardHashes(): Promise<CardHashIndex> {
  if (!loadPromise) {
    loadPromise = (async () => {
      try {
        const response = await fetch(`${import.meta.env.BASE_URL}card-hashes.jsonl`, {
          headers: { Accept: 'application/x-ndjson' }
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const text = await response.text();

        let region: FrameRectLike = HASH_ART_REGION;
        let threshold = HASH_MATCH_THRESHOLD;
        const entries: CardHashEntry[] = [];
        for (const rawLine of text.split('\n')) {
          const line = rawLine.trim();
          if (!line) continue;
          let rec: unknown;
          try {
            rec = JSON.parse(line);
          } catch {
            continue; // tolerate a torn final line from an interrupted build
          }
          if (typeof rec !== 'object' || rec === null) continue;
          const obj = rec as CardHashLine;
          if (obj.type === 'meta') {
            const r = obj.region;
            if (r && [r.x0, r.y0, r.x1, r.y1].every(v => typeof v === 'number')) region = r;
            if (typeof obj.threshold === 'number') threshold = obj.threshold;
            continue;
          }
          if (obj.type) continue; // done markers / unknown record types
          const entry = obj as { id: string; name?: string; face?: number; hashes: Record<string, string[]> };
          if (!entry.id || !isUsableHashes(entry.hashes)) continue;
          entries.push({ id: entry.id, name: entry.name ?? '', face: entry.face ?? 0, hashes: entry.hashes });
        }

        index = {
          ready: entries.length > 0,
          entries,
          region,
          threshold
        };
      } catch (err) {
        console.warn('Failed to load card hash index — OCR will be the only identification channel:', err);
        // index stays { ready: false } → hash channel skipped, OCR unaffected
      }
      return index;
    })();
  }
  return loadPromise;
}

/** True once the index is loaded and usable for matching. */
export function isCardHashesReady(): boolean {
  return index.ready;
}